ct-controls"></div><div class="board-navigation" role="group" aria-label="Área do jogo e navegação de níveis">${game!=='desvio'&&!custom?'<button id="c-level-prev" class="level-arrow" aria-label="Nível anterior" title="Nível anterior">←</button>':''}<div id="c-board-surface" class="collection-board-wrap experiment ${game==='elo'?`elo-board-surface ${Object.keys(level.constraints?.rowCounts??{}).length||Object.keys(level.constraints?.colCounts??{}).length||level.constraints?.cuts?.length?'elo-has-gutter':''}`:''}"><div id="c-board" class="collection-board" role="group" aria-label="Tabuleiro ${META[game].name}"></div><div id="c-brush-cursor" class="brush-cursor" aria-hidden="true" hidden></div><div id="c-motion" class="result-motion" aria-hidden="true"></div></div>${game!=='desvio'&&!custom?'<button id="c-level-next" class="level-arrow" aria-label="Próximo nível" title="Próximo nível">→</button>':''}</div>${game!=='desvio'?'<div class="pacto-check-controls"><button id="c-check" aria-describedby="c-check-help">Checar</button><span id="c-check-help" class="collection-small" hidden></span><p id="c-check-status" class="pacto-check-status" role="status" aria-live="polite" aria-atomic="true" hidden></p></div>':''}<div id="c-local-palette" class="local-palette" hidden></div><div class="collection-feedback">${isSymbol()||game==='elo'?'<p id="c-live-errors" class="live-errors" role="status" aria-live="polite" aria-atomic="true" hidden></p>':''}<p id="c-status" role="status" aria-live="polite"></p><div id="c-details"></div></div><div class="level-actions"><button id="c-confirm" class="primary confirm">${game==='desvio'?'Confirmar jogada':'Confirmar resposta'}</button><div class="collection-toolbar"><button id="c-undo">↶ Desfazer</button><button id="c-redo">↷ Refazer</button><button id="c-reset" class="action-reset">↺ Reiniciar</button>${game==='desvio'?'<button id="c-hint" class="action-hint">✦ Dicas</button><button id="c-rematch">Revanche · inverter início</button><button id="c-analysis">Analisar posição / prévia</button><button id="c-review">Revisar decisões</button>':'<button id="c-answer" hidden aria-describedby="c-answer-help">Ver gabarito</button><button id="c-hint" class="action-hint">✦ Dicas</button><button id="c-next">Próximo nível →</button>'}</div>${level.tutorial?`<button id="c-guided">Explicar passo do tutorial · ${tutorialStep+1}/3</button>`:''}${game!=='desvio'?'<p id="c-answer-help" class="collection-small" hidden>O gabarito monta uma solução padrão e preserva as pistas fixas. Depois, confirme para conferir. A resolução será identificada como assistida.</p>':''}<button id="c-hint-apply" hidden>Aplicar esta dedução</button><p id="c-hint-text" class="hint" role="status"></p></div>${game==='desvio'?'<div id="c-replay" class="collection-replay"></div>':''}</div><aside id="c-rules-sidebar" class="rules-sidebar" aria-label="Regras e como jogar" ${rulesOpen?'':'hidden'}><h3 id="c-rules-context-title">${esc(rulesContext().title)}</h3><p id="c-rules-context-text" class="rules-context">${esc(rulesContext().text)}</p><div class="rules-body"><p>${META[game].rules}</p>${game==='elo'?eloRulesMarkup(level):''}<div class="collection-notes">${notes()}${game==='elo'?`<p><strong>${!custom?`Etapa ${level.stage??Math.floor(index/20)+1} · ${esc(level.stageName??ELO_STAGES[Math.floor(index/20)]?.[0]??'')}`:'Mecânicas desta fase'}:</strong> ${esc(eloMechanicNames(level))}</p>`:level.lesson?`<p><strong>Foco deste nível:</strong> ${esc(level.lesson)}</p>`:''}${level.difficulty?`<p>Dificuldade ${game==='elo'?'editorial':'técnica'}: ${esc(level.difficulty)}. Você pode escolher qualquer nível.</p>`:''}</div><details class="rules-more"><summary>Estratégias e acessibilidade</summary><div>${strategy()}<p>Tab percorre controles. No tabuleiro, as setas movem o foco; Enter ou espaço aplica a ferramenta selecionada. Pistas fixas têm um pequeno ponto e não podem ser apagadas. Erros explícitos em PACTO recebem hachuras vermelhas após 2 segundos, surgindo suave