@media(max-width:600px){.rules-sidebar{padding:20px 16px}}

/* Compact native disclosure sits immediately before the existing advanced toggle. */
.rules-heading-tools,.stage-tools{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}
.rules-heading-tools{flex-shrink:0}
.rules-heading-tools>.rules-card,.stage-tools>.rules-card{margin:0;border-radius:11px;box-shadow:none;overflow:visible;flex:0 0 auto}
.rules-heading-tools>.rules-card>summary,.stage-tools>.rules-card>summary{min-height:44px;padding:10px 12px;gap:8px;font-size:12px;cursor:pointer}
.rules-heading-tools>.rules-card .rules-show,.rules-heading-tools>.rules-card .rules-hide,.stage-tools>.rules-card .rules-show,.stage-tools>.rules-card .rules-hide{font-size:11px;padding:2px 7px}
@media(max-width:600px){
 .rules-heading-tools{width:100%;justify-content:flex-start;flex-shrink:1}
 .stage-tools{justify-content:flex-start}
 .rules-heading-tools>.rules-card,.stage-tools>.rules-card{max-width:100%}
 .rules-heading-tools>.rules-card>summary,.stage-tools>.rules-card>summary{font-size:11px;padding:9px 10px}
}
